import java.util.*;
import java.math.*;

public class Main {
    static final int MAXN = 250015;
    static long[] inv = new long[MAXN];
    static long[] p = new long[MAXN];

    static void precompute(int maxNum, long mod) {
        inv[0] = inv[1] = 1;
        p[0] = p[1] = 1;
        for (int i = 2; i <= maxNum; i++) {
            inv[i] = (mod - mod / i) * inv[(int)(mod % i)] % mod;
            p[i] = p[i - 1] * i % mod;
        }
        for (int i = 2; i <= maxNum; i++) {
            inv[i] = inv[i - 1] * inv[i] % mod;
        }
    }

    static long fast_pow(long base, long exp, long mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long k = sc.nextLong();
        long mod = sc.nextLong();

        precompute((int) n + 5, mod);

        if (n % 2 == 1) {
            System.out.println(fast_pow(k, n, mod));
        } else {
            List<Integer> special = new ArrayList<>();
            for (int i = 2; i <= n; i += 2) {
                if ((i & n) == i) special.add(i);
            }

            int maxIter = (int) Math.min(17, k);
            long[][] dp = new long[20][(int) n + 1];
            for (int i = 0; i < 20; i++) {
                Arrays.fill(dp[i], 0);
            }
            long total = 0;
            dp[0][(int) n] = 1;

            for (int i = 1; i <= maxIter; i++) {
                long sum = 0;
                for (int x : special) {
                    if (dp[i - 1][x] == 0) continue;
                    int mask = x & (x - 1);
                    int step = mask ^ x;
                    for (int val = step; val <= mask; val += step) {
                        if ((val & mask) == val) {
                            long val_dp = dp[i - 1][x] * p[x] % mod * inv[val] % mod * inv[x - val] % mod;
                            dp[i][val] = (dp[i][val] + val_dp) % mod;
                        }
                    }
                    sum = (sum + dp[i - 1][x]) % mod;
                }
                total = (total + sum * inv[k - i] % mod) % mod;
            }
            long result = total * p[(int) k] % mod;
            long answer = fast_pow(k, n, mod) - result;
            answer = ((answer % mod) + mod) % mod;
            System.out.println(answer);
        }
        sc.close();
    }
}

